import{_ as a,o as i,c as s,a2 as t}from"./chunks/framework.CjcFWkVi.js";const k=JSON.parse('{"title":"Návod na upgrade","description":"Nekompatibilné zmeny medzi hlavnými verziami Nette API od 1.x po 3.x, ako upraviť kód a čo má zmeniť plánovaná verzia 4.0. Návod sa vedie po anglicky.","frontmatter":{"title":"Návod na upgrade","description":"Nekompatibilné zmeny medzi hlavnými verziami Nette API od 1.x po 3.x, ako upraviť kód a čo má zmeniť plánovaná verzia 4.0. Návod sa vedie po anglicky."},"headers":[],"relativePath":"sk/upgrade.md","filePath":"sk/upgrade.md","lastUpdated":1793348601000}'),n={name:"sk/upgrade.md"};function o(r,e,l,p,d,h){return i(),s("div",null,[...e[0]||(e[0]=[t(`<div class="info custom-block"><p class="custom-block-title">INFO</p><p>Návod na upgrade sa vedie po anglicky, rovnako ako v repozitári.</p></div><h1 id="upgrade" tabindex="-1">UPGRADE <a class="header-anchor" href="#upgrade" aria-label="Permalink to &quot;UPGRADE&quot;">​</a></h1><h2 id="upgrade-from-1-x-to-2-0-0" tabindex="-1">Upgrade from 1.x to 2.0.0 <a class="header-anchor" href="#upgrade-from-1-x-to-2-0-0" aria-label="Permalink to &quot;Upgrade from 1.x to 2.0.0&quot;">​</a></h2><h3 id="splitted-inputparam-to-multiple-subclasses" tabindex="-1">Splitted InputParam to multiple subclasses <a class="header-anchor" href="#splitted-inputparam-to-multiple-subclasses" aria-label="Permalink to &quot;Splitted InputParam to multiple subclasses&quot;">​</a></h3><p>InputParam is now abstract class and all types have their own classes. Also InputParam is more like Nette Form inputs with fluent API.</p><p>Examples of replacements:</p><p>Required GET input with available values:</p><p>Old:</p><div class="language-php vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">php</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">new</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> InputParam</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">InputParam</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">::</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">TYPE_GET</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;status&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">InputParam</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">::</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">REQUIRED</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;ok&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;error&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">])</span></span></code></pre></div><p>New:</p><div class="language-php vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">php</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">new</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> GetInputParam</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;status&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">))</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">setRequired</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">setAvailableValues</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">([</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;ok&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;error&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">])</span></span></code></pre></div><p>Multiple optional FILE input:</p><p>Old:</p><div class="language-php vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">php</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">new</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> InputParam</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">InputParam</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">::</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">TYPE_FILE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;myfile&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">InputParam</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">::</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">OPTIONAL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">null</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>New:</p><div class="language-php vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">php</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">new</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> FileInputParam</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;myfile&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">))</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">setMulti</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span></span></code></pre></div><p>For more info about types, see readme section Input Types.</p><h3 id="removed-support-for-old-php-versions" tabindex="-1">Removed support for old PHP versions <a class="header-anchor" href="#removed-support-for-old-php-versions" aria-label="Permalink to &quot;Removed support for old PHP versions&quot;">​</a></h3><p>New version does not support PHP versions 5.6 and 7.0 and also hhvm. Please use it with newer versions of PHP (&gt;7.1)</p><h3 id="updated-dependencies" tabindex="-1">Updated dependencies <a class="header-anchor" href="#updated-dependencies" aria-label="Permalink to &quot;Updated dependencies&quot;">​</a></h3><p>Version 2.0.0 requires nette packages in version 3.0, so probably you will have to upgrade whole nette application.</p><h3 id="typehints" tabindex="-1">Typehints <a class="header-anchor" href="#typehints" aria-label="Permalink to &quot;Typehints&quot;">​</a></h3><p>There are some breaking changes because of added typehints:</p><h4 id="apiauthorizationinterface" tabindex="-1">ApiAuthorizationInterface <a class="header-anchor" href="#apiauthorizationinterface" aria-label="Permalink to &quot;ApiAuthorizationInterface&quot;">​</a></h4><p>Add typehints to methods:</p><ul><li><code>authorized(): bool</code></li><li><code>getErrorMessage(): ?string</code></li></ul><h4 id="apihandlerinterface" tabindex="-1">ApiHandlerInterface <a class="header-anchor" href="#apihandlerinterface" aria-label="Permalink to &quot;ApiHandlerInterface&quot;">​</a></h4><p>Add typehints to methods:</p><ul><li><code>params(): array</code></li><li><code>handle(array $params): Tomaj\\NetteApi\\Response\\ResponseInterface</code></li></ul><h4 id="apiloggerinterface" tabindex="-1">ApiLoggerInterface <a class="header-anchor" href="#apiloggerinterface" aria-label="Permalink to &quot;ApiLoggerInterface&quot;">​</a></h4><p>Add typehints to method:</p><ul><li><code>log(int $responseCode, string $requestMethod, string $requestHeader, string $requestUri, string $requestIp, string $requestAgent, int $responseTime): bool</code></li></ul><h4 id="bearertokenrepositoryinterface" tabindex="-1">BearerTokenRepositoryInterface <a class="header-anchor" href="#bearertokenrepositoryinterface" aria-label="Permalink to &quot;BearerTokenRepositoryInterface&quot;">​</a></h4><p>Add typehints to methods:</p><ul><li><code>validToken(string $token): bool</code></li><li><code>ipRestrictions(string $token): ?string</code></li></ul><h4 id="ipdetectorinterface" tabindex="-1">IpDetectorInterface <a class="header-anchor" href="#ipdetectorinterface" aria-label="Permalink to &quot;IpDetectorInterface&quot;">​</a></h4><p>Add typehints to method:</p><ul><li><code>getRequestIp(): string</code></li></ul><h4 id="paraminterface" tabindex="-1">ParamInterface <a class="header-anchor" href="#paraminterface" aria-label="Permalink to &quot;ParamInterface&quot;">​</a></h4><p>Add typehints to methods:</p><ul><li><code>isValid(): bool</code></li><li><code>getKey(): string</code></li></ul><h4 id="endpointinterface" tabindex="-1">EndpointInterface <a class="header-anchor" href="#endpointinterface" aria-label="Permalink to &quot;EndpointInterface&quot;">​</a></h4><p>Add typehints to methods:</p><ul><li><code>getMethod(): string</code></li><li><code>getVersion(): int</code></li><li><code>getPackage(): string</code></li><li><code>getApiAction(): ?string</code></li><li><code>getUrl(): string</code></li></ul><h3 id="changed-behavior" tabindex="-1">Changed behavior <a class="header-anchor" href="#changed-behavior" aria-label="Permalink to &quot;Changed behavior&quot;">​</a></h3><p>API handler tripplet (array of endpoint, handler, authorization) has been changed to class <code>Api</code> which has methods <code>getEndpoint()</code>, <code>getHandler()</code> and <code>getAuthorization()</code>.</p><h3 id="renamed-methods" tabindex="-1">Renamed methods <a class="header-anchor" href="#renamed-methods" aria-label="Permalink to &quot;Renamed methods&quot;">​</a></h3><p>Few methods have been renamed, please use their new versions:</p><ul><li><code>ApiDecider::addApiHandler()</code> -&gt; <code>ApiDecider::addApi()</code></li><li><code>ApiDecider::getApiHandler()</code> -&gt; <code>ApiDecider::getApi()</code></li><li><code>ApiDecider::getHandlers()</code> -&gt; <code>ApiDecider::getApis()</code></li></ul><h3 id="final-methods" tabindex="-1">Final methods <a class="header-anchor" href="#final-methods" aria-label="Permalink to &quot;Final methods&quot;">​</a></h3><p>BaseHandler now have few final methods:</p><ul><li><code>setEndpointIdentifier</code></li><li><code>getEndpoint</code></li><li><code>setupLinkGenerator</code></li><li><code>createLink</code></li></ul><h3 id="removed-class" tabindex="-1">Removed class <a class="header-anchor" href="#removed-class" aria-label="Permalink to &quot;Removed class&quot;">​</a></h3><p>Class ApiResponse has been removed. Use JsonApiResponse instead.</p><h3 id="removed-params" tabindex="-1">Removed params <a class="header-anchor" href="#removed-params" aria-label="Permalink to &quot;Removed params&quot;">​</a></h3><p>Parameters $parent and $name have been removed from ApiListingControl. New usage is:</p><div class="language-php vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">php</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">new</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> ApiListingControl</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">($apiDecider)</span></span></code></pre></div><h3 id="changed-params" tabindex="-1">Changed params <a class="header-anchor" href="#changed-params" aria-label="Permalink to &quot;Changed params&quot;">​</a></h3><p>Some parameters were strictly typed:</p><ul><li>second parameter in <code>JsonApiResponse::__construct</code> (<code>$payload</code> formerly known as <code>$data</code>) is now <code>array</code></li><li>fifth parameter in <code>JsonApiResponse::__construct</code> (<code>$expiration</code>) is now <code>DateTimeInteface</code> or <code>null</code></li><li>fourth parameter in <code>InputParam::__construct</code> (<code>$availableValues</code>, now parameter of method <code>setAvailableValues()</code>) is now <code>array</code></li></ul><h3 id="changed-events" tabindex="-1">Changed events <a class="header-anchor" href="#changed-events" aria-label="Permalink to &quot;Changed events&quot;">​</a></h3><p>Registration of event onClick in ApiListingControl has been changed. Use:</p><div class="language-php vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">php</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$apiListing</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">onClick[] </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> function</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ($method, $version, $package, $apiAction) {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    ...</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">};</span></span></code></pre></div><h3 id="features" tabindex="-1">Features <a class="header-anchor" href="#features" aria-label="Permalink to &quot;Features&quot;">​</a></h3><p>With new version of Nette API you can:</p><ul><li>add description to your API handlers, also you can mark some handlers as deprecated and add tags for them.</li><li>add description, default value and example for all your input params.</li><li>add list of possible outputs which are validate before response is sent to user. If output is not valid, error is sent.</li></ul><h2 id="caste-otazky" tabindex="-1">Časté otázky <a class="header-anchor" href="#caste-otazky" aria-label="Permalink to &quot;Časté otázky&quot;">​</a></h2><h3 id="existuje-navod-pre-2-x-na-3-0" tabindex="-1">Existuje návod pre 2.x na 3.0? <a class="header-anchor" href="#existuje-navod-pre-2-x-na-3-0" aria-label="Permalink to &quot;Existuje návod pre 2.x na 3.0?&quot;">​</a></h3><p>Samostatný nie. Nekompatibilné zmeny 3.0.0 sú položky [BC] v <a href="/nette-api/sk/changelog.html">changelogu</a>: <code>DefaultHandler</code> vracia <code>404</code> namiesto <code>400</code>, <code>ApiDecider</code> dostane DI kontajner a output configurator aj <code>error handler</code> treba zaregistrovať ako služby.</p><h3 id="existuje-4-0-na-ktoru-sa-da-prejst" tabindex="-1">Existuje 4.0, na ktorú sa dá prejsť? <a class="header-anchor" href="#existuje-4-0-na-ktoru-sa-da-prejst" aria-label="Permalink to &quot;Existuje 4.0, na ktorú sa dá prejsť?&quot;">​</a></h3><p>Zatiaľ nie. 3.x je aktuálna rada. Verzia 4.0 sa vyvíja vo vetve <code>master</code>: potrebuje PHP 8.4 alebo novšie a jej doterajšie nekompatibilné zmeny sú v <a href="https://github.com/tomaj/nette-api/blob/master/UPGRADE-4.0.md" target="_blank" rel="noreferrer">UPGRADE-4.0.md</a>. Na GitHube je otvorený <a href="https://github.com/tomaj/nette-api/milestone/9" target="_blank" rel="noreferrer">milník 4.0.0</a> s plánovanými nekompatibilnými zmenami, napríklad odstránením nebezpečného režimu CORS <code>&#39;auto&#39;</code> a vyššou minimálnou verziou PHP. Dátum vydania zatiaľ nie je; viac vo <a href="/nette-api/sk/guide/versioning.html">Verziách tejto dokumentácie</a>.</p><h3 id="aku-verziu-php-potrebuje-3-x" tabindex="-1">Akú verziu PHP potrebuje 3.x? <a class="header-anchor" href="#aku-verziu-php-potrebuje-3-x" aria-label="Permalink to &quot;Akú verziu PHP potrebuje 3.x?&quot;">​</a></h3><p>PHP 8.3 alebo novšie, pozrite si <a href="/nette-api/sk/guide/getting-started.html#poziadavky">Začíname</a>.</p>`,73)])])}const u=a(n,[["render",o]]);export{k as __pageData,u as default};
